function render(){let model=$('smodel').value,age=$('sage').value,q=$('ssearch').value.trim().toLowerCase();let all=SIGNALS.filter(r=>(model==='all'||r.model===model)&&(age==='all'||r.decision_age_sessions<=+age)&&(!q||`${r.symbol} ${r.name}`.toLowerCase().includes(q)));all.sort((a,b)=>a.decision_age_sessions-b.decision_age_sessions||a.model.localeCompare(b.model)||b.score-a.score);$('sstatus').textContent=`${all.length}条模型观察 / ${new Set(all.map(x=>x.symbol)).size}只证券；分数只在本模型内排序。`;$('scounts').innerHTML=Object.keys(LABELS).map(m=>`<div class="stat"><span>${m} · ${LABELS[m]}</span><strong>${SIGNALS.filter(r=>r.model===m&&r.signal_date===TARGET).length}条今日新增</strong><small>最近信号 ${SIGNALS.filter(r=>r.model===m).map(r=>r.signal_date).sort().at(-1)||'无'} · 当前筛选${all.filter(r=>r.model===m).length}条</small></div>`).join('');$('srows').innerHTML=all.map(r=>`<tr><td><strong>${esc(r.name)}</strong> ${esc(r.symbol)}${window.RECENT_COMPANIES?.companies[r.symbol]?`<br><button class="rf-button" data-rf-company="${esc(r.symbol)}">查看生意与估值</button>`:''}<br><small>${esc(r.model)} · ${esc(LABELS[r.model])}</small></td><td>${esc(r.signal_date)}<br><small>初始信号已过${num(r.signal_age_sessions,0)}日；${r.decision_t!==r.signal_t?'确认 '+esc(r.decision_date):'当日完成条件'}</small></td><td>${num(r.ratio_history20)}倍</td><td>${num(r.ratio_previous_day)}倍</td><td>${r.change_since_signal_pct==null?'未同口径重建':num(r.change_since_signal_pct)+'%'}<br><small>收盘 ${num(r.latest_close)}元</small></td><td>${r.entry_date?esc(r.entry_date):'下一开盘待执行'}<br><small>${r.entry_execution_status==='ok'?'历史执行已核算':r.entry_execution_status==='future_session_pending'?'未来执行未知':esc(r.entry_execution_status)}</small></td><td>${num(r.score,4)}</td></tr>`).join('')||'<tr><td colspan="7">本筛选没有新信号。</td></tr>';window.SIGNALS_CURRENT={records:all.length,latest:TARGET};}
